import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

const weatherTool: ToolDefinition = {
  name: 'get_weather',
  description: 'Get the current weather for a location.',
  inputSchema: {
    type: 'object',
    properties: {
      location: {type: 'string', description: 'City name'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit'], description: 'Temperature units'},
    },
    required: ['location'],
  },
};

describe('ToolRegistry', () => {
  it('throws at registration when inputSchema is not a valid JSON Schema and allows conforming input through to the executor', async () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {type: 'not_a_json_schema_type'},
        },
        async () => 'unreachable'
      )
    ).toThrow(/schema/i);

    const received: Array<Record<string, unknown>> = [];
    registry.register(weatherTool, async input => {
      received.push(input);
      return JSON.stringify({temp: 18, location: input.location});
    });

    const response = await registry.execute('get_weather', {location: 'Berlin', units: 'celsius'});
    expect({response, received}).toEqual({
      response: {result: JSON.stringify({temp: 18, location: 'Berlin'})},
      received: [{location: 'Berlin', units: 'celsius'}],
    });
  });
});

