import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

const outcomeOfSync = (call: () => unknown): string => {
  try {
    call();
    return 'returned without throwing';
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
};

describe('ToolRegistry', () => {
  it('throws at registration naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();
    const message = outcomeOfSync(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {type: 'not_a_json_schema_type'},
        },
        async () => 'unreachable'
      )
    );

    expect({
      mentionsTool: message.includes('bad_schema_tool'),
      mentionsSchema: /schema/i.test(message),
    }).toEqual({
      mentionsTool: true,
      mentionsSchema: true,
    });
  });

  it('compiles a static tool inputSchema once at registration across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const rawSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition: ToolDefinition = {
      name: 'get_weather',
      description: 'Get the current weather for a location.',
      get inputSchema() {
        schemaReads += 1;
        return rawSchema;
      },
    };

    registry.register(definition, async input => String(input.location));
    const readsAtRegister = schemaReads;

    for (let i = 0; i < 10; i++) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect({readsAtRegister, readsAfterTenExecutes: schemaReads}).toEqual({
      readsAtRegister: 1,
      readsAfterTenExecutes: 1,
    });
  });

  it('resolves a function-valued tool definition per call and caches compiled validators by schema reference', async () => {
    const registry = new ToolRegistry();
    let schemaAReads = 0;
    let schemaBReads = 0;
    const schemaA: Record<string, unknown> = {
      type: 'object',
      get properties() {
        schemaAReads += 1;
        return {city: {type: 'string'}};
      },
      required: ['city'],
    };
    const schemaB: Record<string, unknown> = {
      type: 'object',
      get properties() {
        schemaBReads += 1;
        return {zipCode: {type: 'string'}};
      },
      required: ['zipCode'],
    };

    let activeSchema = schemaA;
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Switches schema dynamically',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const readsAtRegister = schemaAReads + schemaBReads;
    await registry.execute('dynamic_lookup', {city: 'Berlin'});
    await registry.execute('dynamic_lookup', {city: 'Paris'});
    activeSchema = schemaB;
    await registry.execute('dynamic_lookup', {zipCode: '10115'});
    await registry.execute('dynamic_lookup', {zipCode: '75001'});

    expect({readsAtRegister, schemaAReads, schemaBReads}).toEqual({
      readsAtRegister: 0,
      schemaAReads: 1,
      schemaBReads: 1,
    });
  });
});

import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

type AjvConstructor = typeof Ajv.default;
const AjvRuntime = Ajv as unknown as AjvConstructor;

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new AjvRuntime({allErrors: true, strict: false, validateFormats: false});
  private readonly compiledSchemas = new WeakMap<Record<string, unknown>, ValidateFunction>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    this.validatorFor(name, tool);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(name: string, tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    const cached = this.compiledSchemas.get(schema);
    if (cached) return cached;
    const compiled = this.compileSchema(name, schema);
    this.compiledSchemas.set(schema, compiled);
    return compiled;
  }

  private compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool "${name}": ${reason}`);
    }
  }
}

