    const registry = new ToolRegistry();
    const registrationError = outcomeOfSync(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {type: 'not_a_json_schema_type'},
        },
        async () => 'unreachable'
      )
    );

    const received: Array<Record<string, unknown>> = [];
    registry.register(weatherTool, async input => {
      received.push(input);
      return JSON.stringify({temp: 18, location: input.location});
    });

    const response = await registry.execute('get_weather', {location: 'Berlin', units: 'celsius'});
    expect({
      rejectedInvalidSchema: /schema/i.test(registrationError),
      response,
      received,
    }).toEqual({
      rejectedInvalidSchema: true,
      response: {result: JSON.stringify({temp: 18, location: 'Berlin'})},
      received: [{location: 'Berlin', units: 'celsius'}],
    });
  });

